function instagramMediaURLs(data){return [...new Set([data.profile.avatar,...data.posts.flatMap(p=>p.media.map(m=>m.url)),...(data.profile.highlights||[]).flatMap(h=>[h.cover,...(h.stories||[]).map(s=>s.src)])].filter(Boolean))]}
function instagramMediaProxy(url){return '/api/instagram/media?url='+encodeURIComponent(url)}
async function createImportedLocalProject(data){
 if(typeof isProjectsHome==='function'&&isProjectsHome()){const id=await projectsSaveCopy(data,data.name);location.assign(projectEditorURL({id}));return}
 await flushProfile();if(!validBackup(data))throw Error('No se pudo preparar un proyecto válido con este perfil.');
 const id=crypto.randomUUID(),database=await new Promise((resolve,reject)=>{const request=indexedDB.open('rio360_'+id,1);request.onupgradeneeded=()=>{request.result.createObjectStore('assets',{keyPath:'id'});request.result.createObjectStore('state',{keyPath:'key'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('No se pudo crear el proyecto en este navegador.'))});
 try{await new Promise((resolve,reject)=>{const tx=database.transaction(['assets','state'],'readwrite');for(const asset of data.assets)tx.objectStore('assets').put(asset);for(const record of [{key:'layout',...data.layout},{key:'profile',data:data.profile},{key:'view',data:data.view}])tx.objectStore('state').put(record);tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(Error('No hay espacio suficiente para guardar la importación.'))})}finally{database.close()}
 let catalog;try{catalog=JSON.parse(localStorage.getItem('rio360_profiles')||'[]')}catch{catalog=[]}if(!Array.isArray(catalog))catalog=[];catalog.push({id,name:data.name});localStorage.setItem('rio360_profiles',JSON.stringify(catalog));localStorage.setItem('rio360_active',id);location.assign('/?project='+encodeURIComponent(id));
}
function instagramProjectData(preview,images){
 const p=preview.profile,assets=[],ids=new Map();for(const [url,image]of images){if(url===p.avatar&&!preview.posts.some(post=>post.media.some(m=>m.url===url)))continue;const asset={id:crypto.randomUUID(),name:'Instagram · '+p.handle+' · '+(assets.length+1),...image};assets.push(asset);ids.set(url,asset.id)}
 const tiles=preview.posts.map(post=>{const media=post.media.map(m=>ids.get(m.url));return {_sharedId:crypto.randomUUID(),imgId:media[0],...(media.length>1?{carouselIds:media}:{}),kind:media.length>1?'carousel':post.video?'reel':'photo',z:1,panX:0,panY:0,caption:post.caption,likes:post.likes,comments:post.comments,views:post.views,date:post.timestamp&&Number.isFinite(new Date(post.timestamp*1000).getTime())?new Date(post.timestamp*1000).toISOString().slice(0,10):'',location:post.location,pinned:post.pinned}});
 const rows=tiles.length<=9?3:tiles.length<=18?6:9;while(tiles.length<rows*3)tiles.push(null);const avatar=p.avatar?images.get(p.avatar):null;
 return {format:'instagram360',version:1,name:p.name+' · Instagram',profile:{handle:p.handle,name:p.name,bio:p.bio,link:p.link,posts:p.posts,followers:p.followers,following:p.following,verified:p.verified,private:p.private,autoPosts:false,avatar:avatar?{src:avatar.src,z:1,panX:0,panY:0,cropVersion:2}:null,highlights:(p.highlights||[]).map(h=>({id:h.id,label:h.label,cover:h.cover?{src:images.get(h.cover).src,z:1,panX:0,panY:0,cropVersion:2}:null,stories:(h.stories||[]).map(story=>({id:story.id,src:images.get(story.src).src}))})),hlOpen:!!p.highlights?.length,category:p.category||'',pronouns:p.pronouns||'',address:'',mutual:'',extraLinks:[],contacts:[],storyRing:'none',followLabel:'Seguir',messageLabel:'Mensaje',ownerEditLabel:'Editar perfil',ownerShareLabel:'Compartir perfil',ownerWebSecondaryLabel:'Ver archivo',showVideo:true,showReposts:true,showTagged:true},layout:{rows,RW:3,RH:4,tiles},assets,view:currentViewSettings()};
}
function openInstagramImporter(){
 const dialog=dom('dialog','instagram-import-dialog'),close=action('×',()=>dialog.close());close.className='ig-import-close';close.setAttribute('aria-label','Cerrar importación');
 dialog.append(close,dom('h2','','Importar Instagram'),dom('p','ig-import-intro','Pegá el enlace de un perfil público para convertirlo en un proyecto editable.'));
 const limits=dom('aside','ig-import-limits');limits.setAttribute('aria-label','Límites de la importación');limits.append(dom('strong','','La importación puede quedar incompleta'),dom('p','','Instagram puede entregar sólo algunas publicaciones y omitir la bio, las cifras o los destacados. Vas a revisar lo disponible antes de crear el proyecto.'));dialog.append(limits);
 const form=dom('form','ig-import-form'),label=dom('label','','Enlace del perfil'),input=dom('input');input.type='text';input.autocomplete='off';input.spellcheck=false;input.maxLength=2048;input.placeholder='https://www.instagram.com/usuario/';input.setAttribute('aria-label','Enlace del perfil');label.append(input);const search=action('Buscar perfil',()=>{});search.type='submit';search.classList.add('btn-accent');form.append(label,search);dialog.append(form);
 const status=dom('p','ig-import-status');status.setAttribute('role','status');const result=dom('div','ig-import-result');dialog.append(status,result);let preview=null,controller=null,busy=false,committing=false;
 const importing=action('Importar como proyecto nuevo',async()=>{
  if(!preview||busy)return;busy=true;importing.disabled=true;input.disabled=true;search.disabled=true;choose.disabled=true;controller=new AbortController();
  try{
   const urls=instagramMediaURLs(preview),images=new Map();let bytes=0;
   for(const [i,url]of urls.entries()){status.textContent='Cargando fotos · '+(i+1)+' de '+urls.length;const response=await fetch(instagramMediaProxy(url),{signal:controller.signal});if(!response.ok)throw Error('No se pudo cargar una foto. Volvé a buscar el perfil para renovar sus enlaces.');const blob=await response.blob();bytes+=blob.size;if(bytes>100*1024*1024)throw Error('El perfil supera los 100 MB de imágenes admitidos por importación.');const image=await readImageFile(new File([blob],'instagram',{type:blob.type}));if(!image)throw Error('Una imagen no se pudo abrir. No se creó ningún proyecto.');images.set(url,image)}
   if(controller.signal.aborted)return;committing=true;close.disabled=true;status.textContent='Guardando el proyecto en este navegador…';const data=instagramProjectData(preview,images);await createImportedLocalProject(data);
  }catch(error){if(error.name!=='AbortError'&&dialog.isConnected)status.textContent=error.message||'No se pudo importar el perfil. Ningún proyecto existente se reemplazó.'}
  finally{committing=false;close.disabled=false;busy=false;importing.disabled=false;input.disabled=false;search.disabled=false;choose.disabled=false}
 });importing.classList.add('btn-accent');importing.hidden=true;const footer=dom('div','ig-import-footer');footer.append(importing,dom('p','ig-import-privacy','La copia queda en este navegador. Sólo se publica si después usás Compartir. No necesitamos tu contraseña de Instagram.'));const saved=dom('details','ig-import-saved');saved.append(dom('summary','','Completar bio, cifras y destacados sin servicios pagos'),dom('p','','En PC, abrí este mismo perfil en Instagram, expandí la bio con «más», esperá que se vean los destacados y guardá la página como HTML (Ctrl+S). Elegí ese archivo acá. No se sube al servidor ni se ejecutan sus scripts.'),dom('p','','Si el navegador ofrece el tipo «sólo HTML», usalo para conservar los enlaces de las portadas. Las historias internas sólo se cargan si están incluidas en el archivo.'));
 const savedInput=dom('input');savedInput.type='file';savedInput.accept='.html,.htm,text/html';savedInput.hidden=true;const choose=action('Elegir HTML del perfil',()=>savedInput.click());saved.append(choose,savedInput);dialog.append(saved,footer);
 savedInput.addEventListener('change',async()=>{const file=savedInput.files?.[0];savedInput.value='';if(!file||busy)return;busy=true;choose.disabled=true;input.disabled=true;search.disabled=true;try{const handle=InstagramImportModel.username(input.value);if(file.size>8*1024*1024)throw Error('El HTML supera los 8 MB.');const base=preview||{profile:{handle,name:handle,bio:'',avatar:null,link:'',followers:'—',following:'—',posts:'—',highlights:[],verified:false,private:false},posts:[],photos:0,availability:{bio:false,highlights:'unavailable'},url:'https://www.instagram.com/'+handle+'/'};const source=await file.text();if(!dialog.isConnected)return;preview=readSavedInstagramPage(base,source);renderPreview()}catch(error){status.textContent=error.message||'No se pudo leer esta página guardada.'}finally{busy=false;choose.disabled=false;input.disabled=false;search.disabled=false}});

 function renderPreview(){const data=preview;result.replaceChildren();
   const identity=dom('div','ig-import-identity');if(data.profile.avatar){const avatar=dom('img');avatar.alt='Avatar de '+data.profile.handle;avatar.src=instagramMediaProxy(data.profile.avatar);identity.append(avatar)}const name=dom('div');name.append(dom('strong','',data.profile.name),dom('span','','@'+data.profile.handle));identity.append(name);result.append(identity);
   const counts=dom('p','ig-import-counts',data.profile.followers+(data.profile.followers==='1'?' seguidor':' seguidores')+' · '+data.profile.following+(data.profile.following==='1'?' seguido':' seguidos')+' · '+data.profile.posts+(data.profile.posts==='1'?' publicación':' publicaciones'));result.append(counts,dom('p','ig-import-bio',data.profile.bio));
   const thumbs=dom('div','ig-import-thumbs');for(const post of data.posts.slice(0,9)){const img=dom('img');img.src=instagramMediaProxy(post.media[0].url);img.alt=post.media.length>1?'Carrusel · '+post.media.length+' fotos':'Publicación';img.loading='lazy';thumbs.append(img)}result.append(thumbs,dom('p','ig-import-summary',data.posts.length+' publicaciones y '+data.photos+' fotos disponibles.'));
   for(const warning of data.warnings)result.append(dom('p','ig-import-warning',warning));const highlights=data.profile.highlights||[];if(highlights.length){const row=dom('div','ig-import-highlights');for(const h of highlights){const item=dom('div');if(h.cover){const image=dom('img');image.src=instagramMediaProxy(h.cover);image.alt=h.label;item.append(image)}item.append(dom('span','',h.label));row.append(item)}result.append(row,dom('p','ig-import-summary',highlights.length+(highlights.length===1?' destacado · ':' destacados · ')+highlights.reduce((n,h)=>n+(h.stories?.length||0),0)+' historias incluidas.'))}status.textContent=data.source==='saved-page'?'Página guardada leída. Revisá los datos recuperados. El archivo se procesó sólo en este navegador.':'Revisá lo que se pudo leer antes de importar.';importing.hidden=false;
 }
 input.addEventListener('input',()=>{preview=null;importing.hidden=true;result.replaceChildren();status.textContent=''});
 form.addEventListener('submit',async event=>{
  event.preventDefault();if(busy)return;let handle;try{handle=InstagramImportModel.username(input.value)}catch(error){status.textContent=error.message;return}busy=true;choose.disabled=true;search.disabled=true;input.disabled=true;preview=null;importing.hidden=true;result.replaceChildren();status.textContent='Consultando el perfil público…';controller=new AbortController();
  try{const response=await fetch('/api/instagram/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profileURL:handle}),signal:controller.signal});if(!response.headers.get('Content-Type')?.includes('application/json'))throw Error('Este alojamiento no admite importar perfiles. Usá ig360.peressa.dev o el servidor de Cloudflare.');const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo consultar el perfil.');if(controller.signal.aborted)return;preview=data;
   renderPreview();
  }catch(error){if(error.name!=='AbortError'&&dialog.isConnected)status.textContent=error.message||'No se pudo consultar el perfil.'}
  finally{busy=false;choose.disabled=false;search.disabled=false;input.disabled=false}
 });
 dialog.addEventListener('cancel',event=>{if(committing)event.preventDefault()});document.body.append(dialog);dialog.addEventListener('close',()=>{controller?.abort();dialog.remove()},{once:true});dialog.showModal();input.focus();
}
function initInstagramImportUI(){const button=action('Importar Instagram',openInstagramImporter);button.id='importInstagram';button.classList.add('instagram-import-entry');$('uploadPhotos').after(button);$('importProfile').textContent='Importar respaldo'}
